  "help.lendingFlexible": "लचीला: कुसै बी भुगतान गी कुसै बी समें पर रिकार्ड करो — आंशिक जां पूर्ण। मासिक: किस्त दे शेड्यूल दा पालन करदा ऐ। एकमुश्त रकम: इक लक्ष्य तारीख, जदूं तुस करी सकदे ओ तां भुगतान करो।",
  "help.pressureWeight": "हर बिल थमां मासिक अनुमान: रकम ÷ दोहरा अंतराल (जैसे ₹3,000 त्रैमासिक → ₹1,000/mo)। इक बारी दे बिलें च पूरी रकम दा इस्तेमाल कीता जंदा ऐ। सिर्फ तुंदे बचाए गेदे बिल — कुसै बी चीजै गी पैह् ले थमां गै भरेआ नेईं जंदा ऐ।",
