  "help.dueThisMonth": "चालू कैलेंडर म्हीने च नियत तारीख आह् ले बिल जेह् ड़े अजें तगर पूरी चाल्ली भुगतान नेईं कीते गेदे न।",
  "help.freeAfterDues": "आय घट्ट करियै आवर्ती ते सक्रिय बिलें थमां अनुमानित मासिक बकाया।",
  "help.dueHeatmap": "अगले चार हफ्तें च हर इक च कितने बिल बकाया होंदे न ते उंदी कुल रकम।",
  "help.debtTrend": "सबनें थमां पुराने ते नमें म्हीने दे बश्कार कुल खुल्लै संतुलन च बदलाव जिसदे लेई असें गी स्नैपशॉट न।",
  "help.chitInstallments": "ज्यादातर बड्डी चिट बराबर मासिक शेयर (मूल्य ÷ महीने) दा इस्तेमाल करदे न। किश समूह घट्ट होने आह् ली किश्तें दा इस्तेमाल करदे न (उच्च जल्दी, घट्ट बाद च)। अपने समूह कन्नै मेल खाने आह् ला टाइप चुनो।",
  "help.chitMonthsPaid": "कितनी किस्तें दा भुगतान पैह्लें गै करी चुके दा ऐ। जेकर तुसें 46 देई दित्ते तां तुस हून 47 महीने पर ओ। इस कन्नै बकाया रकम ते महीने दा नंबर तय कीता जंदा ऐ।",
  "help.chitPayoutReceived": "असल नकदी तुसेंगी उसलै मिली ही जिसलै तुसें चिट लेई ही (जैसे ₹4,43,000)। अस इस थमां नीलामी छूट दा कम्म करदे आं — तुसेंगी छूट दा अंदाजा लाने दी लोड़ नेईं ऐ।",
  "help.chitForeman": "आयोजक कमीशन, अक्सर चिट वैल्यू दा 5% दे आसपास, जदूं तुसेंगी पैसे मिलदे न तां बर्तन थमां लैता जंदा ऐ।",
  "help.chitDiscount": "नीलामी च तुस पूरी चिट वैल्यू थमां घट्ट स्वीकार करदे ओ — एह् छूट होर सदस्यें कन्नै साझा कीती जंदी ऐ। तुसेंगी कदें बी पूरी चिट रकम नकद च नेईं मिलदी।",
  "help.chitAdvisor": "महीने दी तुलना करदा ऐ जिसलै तुस चिट लेई सकदे ओ: अनुमानित छूट, फोरमैन दे बाद भुगतान, उस महीने तुंदे होर बिल, ते इक मैक्स नुकसान जेह् ड़ा तुस स्वीकार करने लेई तैयार ओ।",
  "help.chitMaxLoss": "अस तुंदी आमदनी, मासिक बकाया, खुल्लै कर्ज, ओवरड्यू बिल, ते बचत थमां मता नुकसान सुझाऽ दिन्दे आं — इक निश्चित % नेईं । जल्दी लेना अक्सर इसदे कोला बी मता होंदा ऐ; बाद दे म्हीनें च आमतौर उप्पर कम खर्च होंदा ऐ ।",
  "help.loanExtraTiming": "आने आह् ले म्हीनें गी दस्सदा ऐ : जदूं होर बिल हल्के होंदे न तां जे तुस इस लोन पर अतिरिक्त भुगतान करी सकदे ओ , ते भारी महीने जिसलै तुसेंगी घट्ट शा घट्ट समें उप्पर अडिग रौह्ना चाहिदा ।",
  "help.incomeEntryBasis": "टेक-होम मेल खांदा ऐ जेह् ड़ा टैक्स, PF, ते फिक्स्ड कटौती दे बाद तुंदे बैंक च उतरदा ऐ — दबाव ते मुफ्त-नकद गणित आस्तै सर्वश्रेष्ठ। सकल तदूं गै उपयोगी होंदा ऐ जेकर तुस दर्ज कीते गेदे हर इक नंबर कर शा पैह् ले होन; जेकर टेक-होम आमदनी सकल थमां घट्ट ऐ तां मुफ्त नकदी तुंदे असल बैंक बैलेंस थमां घट्ट दिक्खी सकदी ऐ।",
