  "wealthDetail.property.holdModerate": "पकड़ने लायक — मामूली असली फायदे",
  "wealthDetail.property.holdModerateDetail": "नाममात्र दी तरक्की महंगाई गी चक्रवृद्धि आधार उप्पर हरांदी ऐ, पर असली रिटर्न मध्यम ऐ। जेकर तुसेंगी तरलता दी लोड़ नेईं ऐ तां पकड़ो; बिक्री सिर्फ इक मजबूत पुनर्निवेश योजना जां जीवन-घटना नकद जरूरत आस्तै गै समझ च औंदा ऐ।",
