  "wealthDetail.property.yearsToTarget": "वर्तमान गति कन्नै, ~{years} 12% सीएजीआर लक्ष्य तगर पुज्जने लेई होर साल।",
  "wealthDetail.property.outlookMetro": "Metro corridors: infra (metro lines, IT parks) often lifts land values — watch local RERA/project news.",
  "wealthDetail.property.outlookTier2": "Tier-2 cities: industrial corridors and highway links can accelerate appreciation in 5–8 year cycles.",
  "wealthDetail.property.outlookTier3": "Smaller towns: liquidity is lower — favour long holds and verify title before major price revisions.",
  "wealthDetail.property.outlookAreaFallback": "अपनी लोकलटी",
  "wealthDetail.property.purchaseThen": "Purchase price (then)",
  "wealthDetail.property.inflationCostToday": "महंगाई-समायोजित लागत (अज्ज)",
  "wealthDetail.property.inflationCostHint": "तुहाडा वर्तमान मूल्य नहीं — मूल खरीददारी दी कीमत अज्ज दे रुपये विच की है।",
  "wealthDetail.property.narrative.inflationAdjustedCost": "Your ₹{purchase} purchase equals roughly ₹{todayEquivalent} in today's money after {years} years at ~{inflation}% compounded inflation — real growth is measured against that, not the original price alone.",
  "wealthDetail.property.narrative.purchaseDerived": "खरीद कीमत दर × क्षेत्र थमां औंदी ऐ जेह् ड़ी तुसें दर्ज कीती ऐ — जेकर कुल गलत दिक्खदा ऐ तां संपादत पर टैप करो.",
  "wealthDetail.property.narrative.realReturnExplain": "Nominal CAGR {cagr}% minus ~{inflation}% inflation ≈ {real}% real return per year — property often looks strong in rupee terms while barely beating inflation after costs.",
  "wealthDetail.property.narrative.vsBenchmarkExplain": "Your {cagr}% CAGR vs ~{benchmark}% typical for this city tier ({delta}% difference) — use as a rough peer check, not a buy/sell signal.",
  "wealthDetail.property.narrative.longHoldLiquidity": "लंबे समें दे होल्ड समें दा जोखिम घट्ट करदे न पर पूंजी गी लॉक करदे न — इसगी बिक्री योग्य धन दे रूप च समझने शा पैह्ले 6-12 म्हीने दे खर्चे गी होर थाह् रें पर तरल रक्खो ।",
  "wealthDetail.property.narrative.rentYieldExplain": "Estimated gross rent yield ~{yield}% — compare with FD/PPF after tax; if you live in the property, treat rent savings as implicit yield.",
  "wealthDetail.property.narrative.rentVsIncome": "जेकर पूरी चाल्ली किराया ऐ तां सकल किराया तुंदी घोशित मासिक आय दा ~{pct}% होग — जांच करो जे केह् एह् तुंदे असली जां हासल करने योग्य किराये कन्नै मेल खांदा ऐ जां नेईं ।",
  "wealthDetail.property.narrative.valueVsIncome": "एह् संपत्ति ~{multiple}× कागज पर तुंदी सालाना आमदनी ऐ — इक बड्डी एकाग्रता; कारक कि आपातकालीन ते विविधता योजना च।",
  "wealthDetail.property.narrative.highValueTier3Liquidity": "इक छोटे शैह् र च इस मूल्य पर, खरीदार गी ढूँढने च महीने लग सकदे न — यथार्थवादी कीमत ते पूर्ण मूल्य गी तुरत उपलब्ध नकदी दे रूप च गिनने थमां बचो।",
  "wealthDetail.property.narrative.highValueTier2Liquidity": "टीयर-2 बाजार आस्तै उच्च टिकट — अपने दस्से गेदे मूल्य पर त्वरित तरलता गी मनने थमां पैह् ले नेड़में हालिया पंजीकृत बिक्री दी सत्यापन करो।",
  "wealthDetail.property.narrative.targetCagrReality": "इत्थूं थमां 12% सीएजीआर दा पीछा करने च अज्जै दी गति कन्नै ~{years} होर साल लगने होङन — तुंदी होल्डिंग ने पैह् ले थमां गै मजबूत नाममात्र फायदे दित्ते; भविष्य च रिटर्न सामान्य होई सकदा ऐ।",
  "wealthDetail.property.narrative.landHold": "जमीन: सबनें थमां घट्ट रखरखाव पर सबनें थमां धीमी तरलता — 10+ साल दे क्षितिजें लेई सर्वश्रेष्ठ; सूचीबद्ध करने थमां पैह् ले भार, ज़ोनिंग, ते सड़क-चौड़ाई आह् ली सूचनाएं दी जांच करो।",
  "wealthDetail.property.narrative.commercialHold": "व्यावसायिक: रिक्ति ते किरायेदार दी गुणवत्ता उतनी गै मायने रखदी ऐ जितना कि स्थान — जेकर फुटफाल जां पट्टे दी शर्तें कमजोर होई जंदी ऐ तां दुबारा आकलन करो।",
  "wealthDetail.property.narrative.residentialHold": "आवासीय: स्व-उपयोग कन्नै बिक्री दा दबाव घट्ट होई जंदा ऐ; जेकर किराया ऐ तां किरायेदारें दे कारोबार ते समाज दे रखरखाव च बढ़ौतरी गी ट्रैक करो।",
  "wealthDetail.property.narrative.verifyTitle": "कुसै बी बिक्री थमां पैह् ले: भार प्रमाण पत्र, संपत्ति कर रसीदें, ते उत्परिवर्तन दी स्थिति — इत्थै देरी कागजी फायदे गी मिटा दिंदी ऐ।",
